import{_ as e,o as i,c as r,ag as o}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"Testing Error Handling","description":"","frontmatter":{},"headers":[],"relativePath":"guides/testing-error-handling.md","filePath":"guides/testing-error-handling.md","lastUpdated":1772297611000}'),s={name:"guides/testing-error-handling.md"};function a(n,t,l,d,p,h){return i(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="testing-error-handling" tabindex="-1">Testing Error Handling <a class="header-anchor" href="#testing-error-handling" aria-label="Permalink to &quot;Testing Error Handling&quot;">​</a></h1><p><strong>Difficulty:</strong> Intermediate | <strong>Time:</strong> 10 minutes</p><p>This tutorial shows you how to systematically test your application&#39;s error-handling paths by using NectoProxy to simulate various failure scenarios. Well-tested error handling is critical, and most bugs hide in the paths developers rarely exercise.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>NectoProxy installed and running</li><li>CA certificate installed in your browser</li><li>Browser proxy configured to use port 8888</li><li>An application you want to test</li></ul><h2 id="scenario-overview" tabindex="-1">Scenario Overview <a class="header-anchor" href="#scenario-overview" aria-label="Permalink to &quot;Scenario Overview&quot;">​</a></h2><p>You will test how your application handles five categories of failure:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>NectoProxy Feature</th><th>What You Test</th></tr></thead><tbody><tr><td>Connection blocked</td><td>Block rule</td><td>Network unreachable / connection refused</td></tr><tr><td>Server error</td><td>Mock rule (500)</td><td>Internal server error handling</td></tr><tr><td>Rate limiting</td><td>Mock rule (429)</td><td>Retry logic, backoff, user feedback</td></tr><tr><td>Timeout</td><td>Delay rule (35s)</td><td>Client-side timeout handling</td></tr><tr><td>Manual modification</td><td>Breakpoints</td><td>Ad-hoc response manipulation</td></tr></tbody></table><h2 id="step-1-test-connection-errors-with-a-block-rule" tabindex="-1">Step 1: Test Connection Errors with a Block Rule <a class="header-anchor" href="#step-1-test-connection-errors-with-a-block-rule" aria-label="Permalink to &quot;Step 1: Test Connection Errors with a Block Rule&quot;">​</a></h2><p>A <strong>Block</strong> rule prevents the request from reaching the server entirely, simulating a scenario where the server is unreachable or the network is down.</p><ol><li><p>Open the <strong>Rules panel</strong> in the NectoProxy Web UI.</p></li><li><p>Click <strong>Add Rule</strong>.</p></li><li><p>Configure:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Block API Endpoint</td></tr><tr><td><strong>Action</strong></td><td>Block</td></tr><tr><td><strong>Match URL</strong></td><td><code>*/api/critical-endpoint</code></td></tr></tbody></table></li><li><p>Click <strong>Save</strong>.</p></li></ol><p>Now navigate to the part of your application that calls this endpoint. Your application should:</p><ul><li>Show a user-friendly error message (not a blank screen or crash).</li><li>Log the error appropriately.</li><li>Offer a retry option if applicable.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The Block action returns a connection error to the client. This is different from returning an HTTP error status code -- it simulates the server being completely unreachable. Use this to test the most severe failure mode.</p></div><h2 id="step-2-test-server-errors-with-a-500-mock" tabindex="-1">Step 2: Test Server Errors with a 500 Mock <a class="header-anchor" href="#step-2-test-server-errors-with-a-500-mock" aria-label="Permalink to &quot;Step 2: Test Server Errors with a 500 Mock&quot;">​</a></h2><p>Create a mock rule that returns a 500 Internal Server Error:</p><ol><li><p>Click <strong>Add Rule</strong> in the Rules panel.</p></li><li><p>Configure:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Mock 500 Error</td></tr><tr><td><strong>Action</strong></td><td>Mock</td></tr><tr><td><strong>Match URL</strong></td><td><code>*/api/critical-endpoint</code></td></tr><tr><td><strong>Status</strong></td><td><code>500</code></td></tr><tr><td><strong>Status Text</strong></td><td><code>Internal Server Error</code></td></tr></tbody></table></li><li><p>Add headers:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td><code>application/json</code></td></tr></tbody></table></li><li><p>Set the body:</p></li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;InternalServerError&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;An unexpected error occurred&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requestId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;req-12345&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="5"><li>Click <strong>Save</strong>.</li><li><strong>Disable</strong> the Block rule from Step 1 so this Mock rule takes effect.</li></ol><p>Test your application. It should:</p><ul><li>Display an appropriate error message to the user.</li><li>Not expose raw error details (like stack traces) to end users.</li><li>Consider offering a retry mechanism.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Make sure to disable or delete conflicting rules when testing different scenarios. If both a Block rule and a Mock rule match the same URL pattern, the rule with higher priority will fire first.</p></div><h2 id="step-3-test-rate-limiting-with-a-429-mock" tabindex="-1">Step 3: Test Rate Limiting with a 429 Mock <a class="header-anchor" href="#step-3-test-rate-limiting-with-a-429-mock" aria-label="Permalink to &quot;Step 3: Test Rate Limiting with a 429 Mock&quot;">​</a></h2><p>Rate limiting is a common API behavior that applications must handle gracefully.</p><ol><li><p>Click <strong>Add Rule</strong>.</p></li><li><p>Configure:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Mock Rate Limit</td></tr><tr><td><strong>Action</strong></td><td>Mock</td></tr><tr><td><strong>Match URL</strong></td><td><code>*/api/critical-endpoint</code></td></tr><tr><td><strong>Status</strong></td><td><code>429</code></td></tr><tr><td><strong>Status Text</strong></td><td><code>Too Many Requests</code></td></tr></tbody></table></li><li><p>Add headers:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td><code>application/json</code></td></tr><tr><td><code>Retry-After</code></td><td><code>60</code></td></tr><tr><td><code>X-RateLimit-Remaining</code></td><td><code>0</code></td></tr><tr><td><code>X-RateLimit-Reset</code></td><td><code>1706900000</code></td></tr></tbody></table></li><li><p>Set the body:</p></li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RateLimitExceeded&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Too many requests. Please try again in 60 seconds.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;retryAfter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="5"><li>Click <strong>Save</strong>.</li><li>Disable the 500 rule from Step 2.</li></ol><p>Test your application. It should:</p><ul><li>Read the <code>Retry-After</code> header and wait before retrying.</li><li>Show the user a meaningful message about the rate limit.</li><li>Implement exponential backoff if appropriate.</li></ul><h2 id="step-4-test-timeout-handling-with-a-delay-rule" tabindex="-1">Step 4: Test Timeout Handling with a Delay Rule <a class="header-anchor" href="#step-4-test-timeout-handling-with-a-delay-rule" aria-label="Permalink to &quot;Step 4: Test Timeout Handling with a Delay Rule&quot;">​</a></h2><p>Use a <strong>Delay</strong> rule to simulate a server that takes too long to respond, triggering your client&#39;s timeout logic.</p><ol><li><p>Click <strong>Add Rule</strong>.</p></li><li><p>Configure:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Simulate Slow Response</td></tr><tr><td><strong>Action</strong></td><td>Delay</td></tr><tr><td><strong>Match URL</strong></td><td><code>*/api/critical-endpoint</code></td></tr><tr><td><strong>Delay</strong></td><td><code>35000</code> (35 seconds)</td></tr></tbody></table></li><li><p>Click <strong>Save</strong>.</p></li><li><p>Disable the 429 rule from Step 3.</p></li></ol><details class="details custom-block"><summary>Why 35 Seconds?</summary><p>The default <code>requestTimeout</code> in NectoProxy is 30,000 ms (30 seconds). A 35-second delay exceeds this timeout, causing NectoProxy itself to abort the request. If your client has its own timeout (e.g., Axios defaults to no timeout, fetch has no built-in timeout), adjust the delay to exceed your client&#39;s timeout value.</p></details><p>Test your application. It should:</p><ul><li>Show a loading indicator while waiting.</li><li>Eventually time out and display an error.</li><li>Not freeze or become unresponsive.</li><li>Offer a way to retry the request.</li></ul><h2 id="step-5-use-breakpoints-for-ad-hoc-modification" tabindex="-1">Step 5: Use Breakpoints for Ad-Hoc Modification <a class="header-anchor" href="#step-5-use-breakpoints-for-ad-hoc-modification" aria-label="Permalink to &quot;Step 5: Use Breakpoints for Ad-Hoc Modification&quot;">​</a></h2><p>Breakpoints let you intercept a request or response in real time and manually modify it before it continues. This is useful for one-off tests that do not warrant creating a permanent rule.</p><ol><li><p>Open the <strong>Breakpoints panel</strong> in the Web UI.</p></li><li><p>Click <strong>Add Breakpoint</strong>.</p></li><li><p>Configure:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Intercept API Response</td></tr><tr><td><strong>Type</strong></td><td>Response</td></tr><tr><td><strong>Match URL</strong></td><td><code>*/api/critical-endpoint</code></td></tr></tbody></table></li><li><p>Click <strong>Save</strong>.</p></li><li><p>Disable all rules from the previous steps.</p></li></ol><p>Now trigger the request from your application. The request goes to the real server, but NectoProxy pauses the response before delivering it to your app:</p><ol><li>The <strong>Intercepted Panel</strong> appears showing the response details.</li><li>You can modify: <ul><li><strong>Status code</strong> -- Change <code>200</code> to <code>503</code> to test service unavailable handling.</li><li><strong>Headers</strong> -- Add, remove, or modify response headers.</li><li><strong>Body</strong> -- Replace the response body with malformed JSON, empty body, or unexpected data.</li></ul></li><li>Click <strong>Resume</strong> to deliver the modified response to your application.</li><li>Click <strong>Abort</strong> to drop the connection entirely.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Breakpoints are powerful for exploratory testing. You can change the response differently each time without creating or modifying rules. The breakpoint timeout (default 30 seconds) auto-continues the request if you do not interact with it in time.</p></div><h2 id="error-handling-checklist" tabindex="-1">Error-Handling Checklist <a class="header-anchor" href="#error-handling-checklist" aria-label="Permalink to &quot;Error-Handling Checklist&quot;">​</a></h2><p>Use this checklist to systematically verify your application&#39;s resilience:</p><ul><li>[ ] <strong>Connection refused:</strong> App shows error, does not crash</li><li>[ ] <strong>500 Internal Server Error:</strong> User sees friendly message</li><li>[ ] <strong>502 Bad Gateway:</strong> Handled distinctly from 500 if applicable</li><li>[ ] <strong>503 Service Unavailable:</strong> Retry logic activates</li><li>[ ] <strong>429 Too Many Requests:</strong> Backoff/retry, respects Retry-After</li><li>[ ] <strong>408 Request Timeout:</strong> Client retries or notifies user</li><li>[ ] <strong>Network timeout:</strong> Loading state resolves, error shown</li><li>[ ] <strong>Malformed JSON response:</strong> App does not crash on parse error</li><li>[ ] <strong>Empty response body:</strong> Handled without null reference errors</li><li>[ ] <strong>Missing required fields:</strong> Validation handles partial data</li><li>[ ] <strong>Slow response (5-10s):</strong> Loading indicator visible</li><li>[ ] <strong>Very slow response (30s+):</strong> Timeout fires correctly</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Test in order of severity:</strong> Start with the most severe failures (connection blocked) and work toward less severe ones (slow responses).</li><li><strong>Combine scenarios:</strong> In production, errors often compound. Try enabling a delay rule alongside a mock error to simulate a slow server that eventually fails.</li><li><strong>Test concurrent failures:</strong> If your app makes multiple API calls, mock errors on one endpoint while leaving others working to verify that partial failures are handled correctly.</li><li><strong>Document expected behavior:</strong> Keep a record of what your app should do in each scenario. This becomes your regression test plan.</li></ul>`,46)])])}const g=e(s,[["render",a]]);export{u as __pageData,g as default};
